-- Insert Quiz Questions for Lesson: Create the Sales Pipeline

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 25 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 25 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm25-create-sales-pipeline' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m25-create-sales-pipeline not found in module 25';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you create pipeline stages?', 
    '["Calendars → Calendar Settings","Opportunities → Pipelines","Sites → Forms","Automation → Workflows"]'::jsonb,
    'Opportunities → Pipelines',
    'Pipeline stages are created in Opportunities → Pipelines. This is where you define the stages that represent your sales process.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should pipeline stage names reflect?', 
    '["The sales rep''s confidence level","Assumptions about the prospect''s budget","Actions taken, not assumptions about qualification","The prospect''s industry or company size"]'::jsonb,
    'Actions taken, not assumptions about qualification',
    'Stage names should reflect actions taken: Call Booked, Call Completed, Proposal Sent. Avoid assumptions like Hot Lead or Qualified. Actions are factual; assumptions are guesses.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is it important to assign stage owners?', 
    '["To track who created the opportunity","To calculate commission automatically","To ensure someone is responsible for moving prospects forward","To limit who can view the pipeline"]'::jsonb,
    'To ensure someone is responsible for moving prospects forward',
    'Assigning owners ensures someone is responsible for updating stages and taking next actions. A pipeline without ownership becomes outdated and useless.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

