-- Insert Quiz Questions for Lesson: Connect Booking to the Opportunity

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 25 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 25 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm25-connect-booking-to-opportunity' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m25-connect-booking-to-opportunity not found in module 25';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What event should start the booking-to-pipeline workflow?', 
    '["Contact Created","Form Submitted","Opportunity Status Changed","Customer Booked Appointment, filtered to the chosen discovery call calendar"]'::jsonb,
    'Customer Booked Appointment, filtered to the chosen discovery call calendar',
    'Use Customer Booked Appointment filtered to your specific discovery call calendar. This ensures only bookings from that calendar create opportunities, not appointments from other calendars.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What action creates a new pipeline card?', 
    '["Add Tag","Create Opportunity, with pipeline and initial stage selected","Send Email","Update Contact"]'::jsonb,
    'Create Opportunity, with pipeline and initial stage selected',
    'Create Opportunity is the action that adds a new card to your pipeline. You must select the correct pipeline and initial stage (typically Call Booked for discovery calls).', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you prefer separate Create Opportunity and Update Opportunity actions?', 
    '["They are newer and look better","They are required for all new accounts","The older combined action is being removed","They give clearer control over when opportunities are created vs updated"]'::jsonb,
    'They give clearer control over when opportunities are created vs updated',
    'Separate Create and Update actions give you clearer control. You know exactly when a new opportunity is created versus when an existing one is updated. This prevents confusion and duplicate records.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

