-- Insert Quiz Questions for Lesson: Manage the Outcome and Next Move

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 25 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 25 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm25-manage-outcome-next-move' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m25-manage-outcome-next-move not found in module 25';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Should a no-show be treated the same as a cancellation?', 
    '["No, they are different statuses requiring different responses","Yes, both should receive the same follow-up message","No, but only cancellations need follow-up","Yes, they are the same thing"]'::jsonb,
    'No, they are different statuses requiring different responses',
    'A no-show and cancellation are different. A no-show may still be interested and needs a polite rebook invitation. A cancellation may indicate disinterest and needs different handling. Treat them as separate statuses.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What trigger handles post-appointment status changes?', 
    '["Opportunity Created","Form Submitted","Appointment Status","Customer Booked Appointment"]'::jsonb,
    'Appointment Status',
    'The Appointment Status trigger fires when an appointment status changes to Showed, No-show, or Cancelled. Use this to automate post-appointment follow-up and pipeline updates.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do when a non-opportunity trigger needs to update a deal?', 
    '["Find the right opportunity first, then update that record","Create a new opportunity every time","Update all opportunities for that contact","Skip the update and handle it manually"]'::jsonb,
    'Find the right opportunity first, then update that record',
    'When a non-opportunity trigger needs to update a deal, first find the correct opportunity for that contact, then update that specific record. This prevents creating duplicates or updating the wrong deal.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

