-- Insert Quiz Questions for Lesson: End-to-End Test and Publish

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 25 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 25 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm25-end-to-end-test-publish' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m25-end-to-end-test-publish not found in module 25';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you use for testing the booking system?', 
    '["A new test contact with an email you can check","A real prospect''s contact details","No testing is needed if the setup looks correct","Your admin account"]'::jsonb,
    'A new test contact with an email you can check',
    'Always use a fresh test contact with an email you can monitor. Your admin account may bypass certain triggers or notifications. Real prospects should never be used for testing.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you verify before publishing workflows?', 
    '["That the workflow is named correctly","That all merge fields are available in the account","That the test booking succeeds without duplicate messages or opportunities","That the workflow has at least five actions"]'::jsonb,
    'That the test booking succeeds without duplicate messages or opportunities',
    'Publish workflows only after testing shows the complete booking journey works: one confirmation, correct reminders, one opportunity, no duplicates. An untested workflow can damage your reputation.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you test cancellation and no-show paths?', 
    '["They are required by data protection laws","To verify correct follow-up actions and message content","To reduce the number of bookings you receive","They are the most common outcomes"]'::jsonb,
    'To verify correct follow-up actions and message content',
    'Testing cancellation and no-show paths verifies that the correct follow-up messages send, opportunities update properly, and no inappropriate reminders continue. These edge cases reveal system gaps.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

