-- Insert Quiz Questions for Lesson: Put the Booking Link to Work

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 25 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 25 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm25-put-booking-link-to-work' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m25-put-booking-link-to-work not found in module 25';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where should you place your booking link?', 
    '["In every email you send, regardless of topic","Every page of your website and all social media posts","Where interested prospects already are, with contextual CTAs","Only on a dedicated landing page"]'::jsonb,
    'Where interested prospects already are, with contextual CTAs',
    'Place the booking link where interested prospects already spend time: email signatures, relevant website pages, social bios, post-event follow-ups. Context matters more than volume.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should your CTA say?', 
    '["Click here to book now!","Book before prices go up","Free consultation — limited time only!","A contextual message that matches the prospect''s situation and need"]'::jsonb,
    'A contextual message that matches the prospect''s situation and need',
    'Contextual CTAs match the prospect''s situation. Want to discuss your next speaking event? Book a 30-minute enquiry call. This is more effective than generic urgency tactics.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you avoid when sharing your booking link?', 
    '["Testing the link before sharing","Sending generic booking requests to everyone","Writing different CTAs for different audiences","Using multiple channels"]'::jsonb,
    'Sending generic booking requests to everyone',
    'Avoid sending generic booking requests to everyone. Target people who have shown interest or fit your audience. Spam damages your reputation and wastes your time on unqualified calls.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

