          <svg class="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z"/></svg>
        </div>
        <div>
          <h4 class="font-semibold text-slate-900">Celebrate</h4>
          <p class="text-sm text-slate-600">A working booking system is a genuine business asset. Acknowledge the achievement.</p>
        </div>
      </div>
    </div>
  </div>

  <!-- Key Point -->
  <div class="bg-gradient-to-r from-amber-50 to-orange-50 rounded-2xl p-6 border-l-4 border-amber-400">
    <div class="flex items-start gap-4">
      <div class="w-12 h-12 rounded-xl bg-amber-100 flex items-center justify-center flex-shrink-0">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg>
      </div>
      <div>
        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">A booking system that is not reviewed becomes outdated. Count bookings, show-ups, and next steps weekly. Identify patterns, pick one improvement, and test it. Assign an owner and schedule recurring reviews. A system that evolves based on data will consistently outperform a system that is set up once and forgotten.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Module 26: Advanced Sales Automation</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Record Baseline</p>
          <p class="text-slate-600 text-sm">Document current bookings, show-ups, and next steps for the past week.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Schedule Reviews</p>
          <p class="text-slate-600 text-sm">Block 15 minutes weekly for system review and improvement.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Pick One Test</p>
          <p class="text-slate-600 text-sm">Choose one improvement to test: reminder timing, CTA wording, or qualification questions.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">4</div>
        <div>
          <p class="font-semibold text-slate-900">Assign Owner</p>
          <p class="text-slate-600 text-sm">Name the person responsible for metrics, review, and updates.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Measure and Improve',
      lesson_number = 12,
      sort_order = 12,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Measure and Improve';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Measure and Improve

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 25 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 25 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm25-measure-and-improve' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m25-measure-and-improve not found in module 25';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are three basic metrics to track weekly?', 
    '["Revenue, profit margin, and customer lifetime value","Video views, blog comments, and podcast downloads","Bookings, show-ups, and completed next steps","Website traffic, social media followers, email open rates"]'::jsonb,
    'Bookings, show-ups, and completed next steps',
    'The three basic metrics are bookings (how many calls scheduled), show-ups (how many attended), and completed next steps (how many led to action). These tell you if the system is working.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do at each weekly review?', 
    '["Compare your metrics to competitor benchmarks","Redesign the entire booking system","Hire a consultant to optimize the system","Count numbers, identify patterns, and pick one improvement to test"]'::jsonb,
    'Count numbers, identify patterns, and pick one improvement to test',
    'At each review, count the numbers, look for patterns, and choose one improvement to test. Small, consistent improvements compound over time. Major redesigns are rarely needed.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is system ownership important?', 
    '["To limit who can use the booking system","To assign blame when things go wrong","To ensure someone is responsible for review, metrics, and improvement","To increase the cost of the system"]'::jsonb,
    'To ensure someone is responsible for review, metrics, and improvement',
    'An owner ensures the system is reviewed, metrics are tracked, and improvements are made. A system without ownership becomes outdated and ineffective. Ownership is about accountability, not blame.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
